const body = $input.first().json.body || $input.first().json;

const name = body.name || '';
const phone = body.phone || '';
const email = body.email || '';
const whatsapp_id = body.whatsapp_id || '';
const message = body.message || '';
const channel = body.channel || 'web';

// Detect language
const arabicRegex = /[\u0600-\u06FF]/;
const latinRegex = /[a-zA-Z]/;
const hasArabic = arabicRegex.test(message);
const hasLatin = latinRegex.test(message);

let detected_language = 'fr';
if (hasArabic && hasLatin) {
  detected_language = 'darija';
} else if (hasArabic) {
  detected_language = 'ar';
}

const message_lower = message.toLowerCase();

return [{
  json: {
    name,
    phone,
    email,
    whatsapp_id,
    message,
    message_lower,
    channel,
    detected_language,
    requestBody: {
      name: name || 'Unknown',
      phone,
      email,
      source: channel,
      preferred_language: detected_language
    }
  }
}];

const input = $('Parse Input').first().json;
const clientRaw = $input.first().json;
const client = Array.isArray(clientRaw) ? clientRaw[0] : clientRaw;
const client_id = client.id;

return [{
  json: {
    client_id,
    requestBody: {
      client_id,
      channel: input.channel,
      status: 'open',
      last_message: input.message
    }
  }
}];

const convRaw = $input.first().json;
const conv = Array.isArray(convRaw) ? convRaw[0] : convRaw;
const conversation_id = conv.id;
const client_id = $('Prep Conversation').first().json.client_id;
const input = $('Parse Input').first().json;

const supabaseUrl = 'YOUR_SUPABASE_URL';
const headersGet = {
  'apikey': 'YOUR_SUPABASE_SERVICE_ROLE_KEY',
  'Authorization': 'Bearer YOUR_SUPABASE_SERVICE_ROLE_KEY'
};
const headersPost = {
  'apikey': 'YOUR_SUPABASE_SERVICE_ROLE_KEY',
  'Authorization': 'Bearer YOUR_SUPABASE_SERVICE_ROLE_KEY',
  'Content-Type': 'application/json',
  'Prefer': 'return=representation'
};

// Try to get existing session
let sessionData = null;
try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: supabaseUrl + '/session_state?conversation_id=eq.' + conversation_id + '&limit=1',
    headers: headersGet
  });
  if (Array.isArray(response) && response.length > 0) {
    sessionData = response[0];
  }
} catch(e) {
  // Session fetch failed
}

// Create session if not exists
if (!sessionData) {
  const newSession = {
    conversation_id,
    client_id,
    current_intent: 'unknown',
    collected_data: {
      name: input.name,
      phone: input.phone,
      quote_stage: 'idle'
    },
    last_tool_used: null
  };
  try {
    const createRes = await this.helpers.httpRequest({
      method: 'POST',
      url: supabaseUrl + '/session_state',
      headers: headersPost,
      body: newSession
    });
    sessionData = Array.isArray(createRes) ? createRes[0] : createRes;
  } catch(e) {
    sessionData = newSession;
  }
}

return [{
  json: {
    conversation_id,
    client_id,
    session_state: sessionData
  }
}];

const session = $input.first().json;
const input = $('Parse Input').first().json;

return [{
  json: {
    conversation_id: session.conversation_id,
    client_id: session.client_id,
    session_state: session.session_state,
    requestBody: {
      conversation_id: session.conversation_id,
      client_id: session.client_id,
      sender_type: 'client',
      content: input.message,
      intent: 'pending'
    }
  }
}];

const session = $('Manage Session State').first().json;
const input = $('Parse Input').first().json;
const conversation_id = session.conversation_id;

const supabaseHeaders = {
  'apikey': 'YOUR_SUPABASE_SERVICE_ROLE_KEY',
  'Authorization': 'Bearer YOUR_SUPABASE_SERVICE_ROLE_KEY'
};

// Fetch conversation history
let history = [];
try {
  const messages = await this.helpers.httpRequest({
    method: 'GET',
    url: 'YOUR_SUPABASE_URL/messages?conversation_id=eq.' + conversation_id + '&order=created_at.asc&limit=20',
    headers: supabaseHeaders
  });
  if (Array.isArray(messages)) {
    history = messages.map(m => ({
      role: m.sender_type === 'client' ? 'user' : 'assistant',
      content: m.content
    }));
  }
} catch(e) {
  history = [];
}

// Build intent classifier request body
const requestBody = {
  model: 'gpt-oss-120b',
  max_tokens: 200,
  response_format: { type: 'json_object' },
  messages: [
    {
      role: 'system',
      content: 'You are an intent classifier for a Moroccan construction company. Classify the user message into exactly ONE intent. Return JSON only, no explanation: { "intent": "...", "confidence": 0.0 } Intents: list_services, list_materials, search_faq, get_projects, get_quotes, create_quote, unknown. Rules: - create_quote = user wants price estimate, devis, or mentions building/renovation project - list_services = asks what services exist - list_materials = asks about materials available - search_faq = asks a general question about the company - get_projects = asks about past projects or portfolio - get_quotes = asks about their existing quotes - unknown = greetings or unclear'
    },
    {
      role: 'user',
      content: input.message
    }
  ]
};

return [{
  json: {
    requestBody,
    conversation_id,
    client_id: session.client_id,
    session_state: session.session_state,
    history
  }
}];

const response = $input.first().json;
const data = $('Prep Intent Request').first().json;

let intent = 'unknown';
let confidence = 0;

try {
  const content = response.choices[0].message.content;
  const parsed = typeof content === 'string' ? JSON.parse(content) : content;
  intent = parsed.intent || 'unknown';
  confidence = parsed.confidence || 0;
} catch(e) {
  intent = 'unknown';
}

// Validate intent against known list
const validIntents = ['list_services', 'list_materials', 'search_faq', 'get_projects', 'get_quotes', 'create_quote', 'unknown'];
if (!validIntents.includes(intent)) {
  intent = 'unknown';
}

return [{
  json: {
    intent,
    confidence,
    conversation_id: data.conversation_id,
    client_id: data.client_id,
    session_state: data.session_state,
    history: data.history
  }
}];

const data = $input.first().json;
const client_id = data.client_id;

return [{
  json: {
    requestUrl: 'YOUR_SUPABASE_URL/quotes?client_id=eq.' + client_id + '&select=*&order=created_at.desc'
  }
}];

const supabaseUrl = 'YOUR_SUPABASE_URL';
const headers = {
  'apikey': 'YOUR_SUPABASE_SERVICE_ROLE_KEY',
  'Authorization': 'Bearer YOUR_SUPABASE_SERVICE_ROLE_KEY'
};

let services = [];
let materials = [];
let knowledge = [];

try {
  services = await this.helpers.httpRequest({
    method: 'GET',
    url: supabaseUrl + '/services?status=eq.active&select=id,name,description,base_price,unit',
    headers
  });
  if (!Array.isArray(services)) services = [];
} catch(e) { services = []; }

try {
  materials = await this.helpers.httpRequest({
    method: 'GET',
    url: supabaseUrl + '/materials?status=eq.active&select=id,name,description,selling_price,unit,stock_quantity',
    headers
  });
  if (!Array.isArray(materials)) materials = [];
} catch(e) { materials = []; }

try {
  knowledge = await this.helpers.httpRequest({
    method: 'GET',
    url: supabaseUrl + '/knowledge_documents?select=*&order=created_at.desc&limit=5',
    headers
  });
  if (!Array.isArray(knowledge)) knowledge = [];
} catch(e) { knowledge = []; }

return [{
  json: {
    tool_result: {
      services,
      materials,
      knowledge_documents: knowledge
    },
    tool_name: 'create_quote'
  }
}];

const allInputs = $input.all().map(i => i.json);
const intentData = $('Parse Intent').first().json;
const intent = intentData.intent;
const input = $('Parse Input').first().json;
const session = $('Manage Session State').first().json;
const history = intentData.history || [];

// Determine tool result based on which branch fed us
let tool_result = [];
let tool_name = intent;

const firstInput = allInputs[0];
if (firstInput && firstInput.tool_result !== undefined) {
  // From Fetch Quote Data or Set Empty Result code nodes
  tool_result = firstInput.tool_result;
  tool_name = firstInput.tool_name || intent;
} else {
  // From HTTP GET nodes — all items are the tool result array
  tool_result = allInputs;
  tool_name = intent;
}

// Build the main AI system prompt
const systemPrompt = `You are an AI assistant for a Moroccan construction and renovation company called Travaux.

RULES:
- Use ONLY data provided in tool_result. Never invent services, prices, or materials.
- Reply in the SAME language as the user's last message (Darija in latin script, French, or Arabic).
- Ask ONE question at a time. Never ask multiple questions in one message.
- Be concise and friendly.
- Always return valid JSON only: { "reply": "string", "status": "complete|incomplete", "session_updates": {} }

FOR create_quote intent:
- Check session_state.collected_data.quote_stage
- If quote_stage is 'idle' or missing: ask project type first, set quote_stage='collecting'
- If quote_stage is 'collecting':
    check what is missing from [project_type, surface_m2, city]
    ask for ONE missing field only
    update collected_data with any new info from message
- If all 3 fields collected: set quote_stage='ready'
- If quote_stage is 'ready':
    select appropriate services from tool_result.services based on project_type
    select appropriate materials from tool_result.materials based on project_type
    calculate quantity per service based on surface_m2
    unit_price = base_price for services, selling_price for materials
    total_price = quantity * unit_price
    price_min = total * 0.85
    price_max = total * 1.20
    set quote_stage='created'
    include in session_updates: { quote_items: [...], quote_total_min: X, quote_total_max: Y }
    reply with summary and price range in user's language

FOR other intents: use tool_result data to answer clearly.`;

// Build user message content
const userContent = JSON.stringify({
  input: {
    message: input.message,
    channel: input.channel,
    name: input.name,
    phone: input.phone
  },
  session_state: {
    current_intent: session.session_state.current_intent || intent,
    collected_data: session.session_state.collected_data || {}
  },
  conversation_history: history.slice(-10),
  tool_name: tool_name,
  tool_result: tool_result
});

return [{
  json: {
    requestBody: {
      model: 'gpt-oss-120b',
      max_tokens: 1000,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userContent }
      ]
    }
  }
}];

const response = $input.first().json;
const intentData = $('Parse Intent').first().json;
const intent = intentData.intent;
const session = $('Manage Session State').first().json;
const conversation_id = session.conversation_id;
const client_id = session.client_id;

// Parse AI response
let reply = '';
let status = 'complete';
let session_updates = {};

try {
  const content = response.choices[0].message.content;
  const parsed = typeof content === 'string' ? JSON.parse(content) : content;
  reply = parsed.reply || '';
  status = parsed.status || 'complete';
  session_updates = parsed.session_updates || {};
} catch(e) {
  reply = 'Désolé, une erreur est survenue. Veuillez réessayer.';
  status = 'complete';
  session_updates = {};
}

// Handle quote creation if AI produced a complete quote
let quote_created = false;
let quote_id = null;

if (intent === 'create_quote' && session_updates.quote_stage === 'created' && session_updates.quote_items && session_updates.quote_items.length > 0) {
  const supabaseUrl = 'YOUR_SUPABASE_URL';
  const headers = {
    'apikey': 'YOUR_SUPABASE_SERVICE_ROLE_KEY',
    'Authorization': 'Bearer YOUR_SUPABASE_SERVICE_ROLE_KEY',
    'Content-Type': 'application/json',
    'Prefer': 'return=representation'
  };

  const quoteNumber = 'QT-' + Date.now();
  const items = session_updates.quote_items;
  const subtotal = items.reduce((sum, item) => sum + (item.total_price || 0), 0);
  const tax = Math.round(subtotal * 0.20 * 100) / 100;
  const total = Math.round((subtotal + tax) * 100) / 100;

  try {
    const quoteRes = await this.helpers.httpRequest({
      method: 'POST',
      url: supabaseUrl + '/quotes',
      headers,
      body: {
        client_id,
        conversation_id,
        quote_number: quoteNumber,
        status: 'draft',
        subtotal,
        tax,
        total,
        currency: 'MAD',
        notes: ''
      }
    });

    const quote = Array.isArray(quoteRes) ? quoteRes[0] : quoteRes;
    quote_id = quote.id;
    quote_created = true;

    // Create each quote item
    for (const item of items) {
      try {
        await this.helpers.httpRequest({
          method: 'POST',
          url: supabaseUrl + '/quote_items',
          headers,
          body: {
            quote_id,
            item_type: item.item_type || 'service',
            service_id: item.service_id || null,
            material_id: item.material_id || null,
            name: item.name || '',
            quantity: item.quantity || 1,
            unit: item.unit || 'unit',
            unit_price: item.unit_price || 0,
            total_price: item.total_price || 0
          }
        });
      } catch(itemErr) {
        // Continue with remaining items
      }
    }
  } catch(quoteErr) {
    quote_created = false;
    quote_id = null;
  }
}

return [{
  json: {
    reply,
    status,
    intent,
    session_updates,
    conversation_id,
    client_id,
    quote_created,
    quote_id
  }
}];

const data = $input.first().json;

return [{
  json: {
    reply: data.reply,
    status: data.status,
    intent: data.intent,
    session_updates: data.session_updates,
    conversation_id: data.conversation_id,
    client_id: data.client_id,
    quote_created: data.quote_created,
    quote_id: data.quote_id,
    requestBody: {
      conversation_id: data.conversation_id,
      client_id: data.client_id,
      sender_type: 'assistant',
      content: data.reply,
      intent: data.intent
    }
  }
}];

const data = $('Prep Save AI Message').first().json;
const session = $('Manage Session State').first().json;
const currentCollected = (session.session_state && session.session_state.collected_data) || {};
const updates = data.session_updates || {};

// Merge existing collected_data with new session_updates
const mergedData = { ...currentCollected, ...updates };

return [{
  json: {
    reply: data.reply,
    status: data.status,
    intent: data.intent,
    quote_created: data.quote_created,
    quote_id: data.quote_id,
    conversation_id: data.conversation_id,
    requestUrl: 'YOUR_SUPABASE_URL/session_state?conversation_id=eq.' + data.conversation_id,
    requestBody: {
      current_intent: data.intent,
      collected_data: mergedData,
      last_tool_used: data.intent
    }
  }
}];

const data = $('Prep Update Session').first().json;

return [{
  json: {
    reply: data.reply,
    status: data.status,
    intent: data.intent,
    quote_created: data.quote_created || false,
    quote_id: data.quote_id || null
  }
}];
